bool IsSimulatedBase(const FMovementBaseInterfaceData* MovementBase)
{
	return (MovementBase && MovementBase->IsValid() && MovementBase->GetBodyInstanceOwner()->IsPhysicsOwnerSimulatingPhysics());
}

FVector GetMovementBaseVelocity(const FMovementBaseInterfaceData* MovementBase, const FName BoneName)
{
	FVector BaseVelocity = FVector::ZeroVector;
	if (IsDynamicBase(MovementBase))
	{
		if (BoneName != NAME_None)
		{
			if (const FBodyInstance* BodyInstance = MovementBase->GetBodyInstanceOwner()->GetBodyInstance(BoneName))
			{
				BaseVelocity = BodyInstance->GetUnrealWorldVelocity();
				return BaseVelocity;
			}
		}

		BaseVelocity = MovementBase->GetBodyInstanceOwner()->GetPhysicsOwnerVelocity();
		if (BaseVelocity.IsZero())
		{
			// Fall back to actor's Root component
			const AActor* Owner = Cast<const AActor>(MovementBase->GetMovementBaseObjectOwner());
			if (Owner)
			{
				// Component might be moved manually (not by simulated physics or a movement component), see if the root component of the actor has a velocity.
				BaseVelocity = Owner->GetVelocity();
			}
		}

		// Fall back to physics velocity.
		if (BaseVelocity.IsZero())
		{
			if (const FBodyInstance* BodyInstance = MovementBase->GetBodyInstanceOwner()->GetBodyInstance())
			{
				BaseVelocity = BodyInstance->GetUnrealWorldVelocity();
			}
		}
	}

